const cfg = $('Normalizar código').first().json;
const p = $('Ler proposta').first().json;
if (!p || !p.id) throw new Error('Envio ao cliente: proposta ' + cfg.codigo + ' não encontrada.');
if (p.estado !== 'aprovada') throw new Error('Envio ao cliente: a proposta ' + p.codigo + ' está no estado ' + p.estado + ' e só se envia no estado aprovada.');
const emailCliente = String(p.contacto_email || '').trim();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(emailCliente)) throw new Error('Envio ao cliente: a proposta ' + p.codigo + ' não tem um email de cliente válido.');
const preco = Number(p.preco_final);
if (!(preco > 0)) throw new Error('Envio ao cliente: a proposta ' + p.codigo + ' ainda não tem preço final (depende da fase 5, Moloni). Nada foi enviado.');
if (!p.token_confirmacao || new Date(p.token_expira_em) < new Date()) throw new Error('Envio ao cliente: a ligação de confirmação da proposta ' + p.codigo + ' expirou ou não existe.');
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const teste = !!cfg.destinatario_teste;
const pt = ['PT', 'BR', 'AO', 'MZ'].includes(String(p.destino_pais || '').toUpperCase());
const link = cfg.url_confirmacao + '?t=' + encodeURIComponent(p.token_confirmacao);
const linha = (k, v) => '<tr><td style="padding:4px 16px 4px 0"><b>' + k + '</b></td><td>' + esc(v) + '</td></tr>';
const valor = preco.toFixed(2) + ' ' + (p.moeda || 'EUR');
const qtd = p.quantidade + ' ' + (p.unidade || 'kg');
const destino = p.destino_pais + (p.destino_local ? ' - ' + p.destino_local : '');
const T = pt
  ? { assunto: 'Proposta comercial - ' + p.produto, ola: 'Exmos. Senhores,', intro: 'Segue a nossa proposta comercial, com a referência <b>' + esc(p.codigo) + '</b>.', prod: 'Produto', den: 'Densidade', gra: 'Granulometria', q: 'Quantidade', emb: 'Embalagem', inc: 'Incoterm', dest: 'Destino', tot: 'Valor total', conf: 'Para confirmar a encomenda, clique na ligação abaixo:', btn: 'Confirmar encomenda', fim: 'Ficamos ao dispor para qualquer esclarecimento.', cump: 'Com os melhores cumprimentos,', sist: 'Equipa comercial (mensagem enviada com o apoio de um sistema automático, revista pela nossa equipa)', teste: 'Email de teste.' }
  : { assunto: 'Commercial proposal - ' + p.produto, ola: 'Dear Sir or Madam,', intro: 'Please find our commercial proposal, reference <b>' + esc(p.codigo) + '</b>.', prod: 'Product', den: 'Density', gra: 'Granulometry', q: 'Quantity', emb: 'Packaging', inc: 'Incoterm', dest: 'Destination', tot: 'Total amount', conf: 'To confirm the order, please click the link below:', btn: 'Confirm order', fim: 'Please do not hesitate to contact us if you need any clarification.', cump: 'Best regards,', sist: 'Sales team (sent with the support of an automated system, reviewed by our team)', teste: 'Test email.' };
const assunto = (teste ? '[TESTE] ' : '') + '[' + p.codigo + '] ' + T.assunto;
const corpo = (teste ? '<p><i>' + T.teste + '</i></p>' : '') + '<p>' + T.ola + '</p><p>' + T.intro + '</p><table>' + linha(T.prod, p.produto) + linha(T.den, p.densidade) + linha(T.gra, p.granulometria) + linha(T.q, qtd) + linha(T.emb, p.embalagem) + linha(T.inc, p.incoterm) + linha(T.dest, destino) + linha(T.tot, valor) + '</table><p>' + T.conf + '</p><p><a href="' + link + '" style="background:#2f6b4f;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none">' + T.btn + '</a></p><p>' + T.fim + '</p><p>' + T.cump + '<br>' + T.sist + '</p>';
const slack = '📤 Proposta *' + p.codigo + '* enviada ao cliente · ' + p.produto + ' · ' + valor + (teste ? ' · (teste, redirecionada)' : '');
return [{ json: { codigo: p.codigo, assunto, corpo_html: corpo, para: teste ? cfg.destinatario_teste : emailCliente, cc: cfg.cc_barbara, slack_texto: slack, idioma: pt ? 'pt' : 'en' } }];
